import {esc,fmt} from '../../ui/format.js';import {PROCESS,effective} from '../../core/model.js';
export function operatorView({m,operationId}){const ops=m.nodes.filter(n=>PROCESS.includes(n.type)),op=ops.find(n=>n.id===operationId)||ops[0];return `<section class="page-intro"><div><div class="eyebrow">LA POSTUL DE LUCRU</div><h1>O operație. Informația relevantă.</h1><p>Consultă resursele și introdu măsurători pentru modelul de analiză.</p></div><span class="badge">Introducere manuală · fără comandă utilaje</span></section><label class="large-select">Alege operația<select id="operator-operation">${ops.map(n=>`<option value="${esc(n.id)}" ${n===op?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label>${!op?'<div class="panel empty"><h2>Nu există operații</h2><p>Adaugă o celulă din biblioteca industrială.</p><button data-page="library">Deschide biblioteca</button></div>':`<div class="operator-grid"><section class="panel"><span class="eyebrow">FIȘA OPERAȚIEI</span><h2>${esc(op.name)}</h2><p>${esc(op.description||'Adaugă instrucțiuni în proprietățile operației.')}</p><div class="operator-cycle"><strong>${fmt(effective(m,op).cycle)}</strong><span>secunde / piesă în model</span></div><h3>Resurse necesare</h3>${m.edges.filter(e=>e.type==='requires'&&e.from===op.id).map(e=>`<div class="resource-row"><span>▣</span><b>${esc(m.nodes.find(n=>n.id===e.to)?.name)}</b><span>× ${e.quantity}</span></div>`).join('')||'<p class="muted">Nicio resursă alocată.</p>'}<p class="small">Instrucțiunile afișate sunt documentația modelului, nu o procedură de lucru aprobată.</p></section><section class="panel"><span class="eyebrow">MĂSURARE</span><h2>Actualizează timpul de ciclu</h2><form id="observation-form"><input type="hidden" name="operation" value="${esc(op.id)}"><label>Timpi măsurați, în secunde<textarea name="samples" placeholder="61; 58; 60; 62; 59" required></textarea><small>Separă măsurătorile prin ; sau rând nou. Pentru zecimale folosește punct.</small></label><label>Condiții / referință măsurare<input name="note" required placeholder="Produs, schimb, metodă de măsurare"></label><p>Media măsurătorilor va actualiza ciclul operației. Dacă parametrul este legat la o variabilă, legătura locală va fi înlocuită.</p><button class="primary">Salvează măsurătorile</button></form></section></div><section class="panel"><h2>Ultimele măsurători</h2>${(m.observations||[]).filter(o=>o.operation===op.id).slice(-8).reverse().map(o=>`<div class="resource-row"><b>${fmt(o.mean)} s</b><span>${o.count} probe · ${esc(o.note)}</span><small>${esc(new Date(o.at).toLocaleString('ro-RO'))}</small></div>`).join('')||'<p class="muted">Nicio măsurare înregistrată.</p>'}</section>`}`}
